SELECT p.id, p.symbol, p.status, p.quantity, p.entry_price, p.stop_loss, p.take_profit, p.exit_price, p.realized_pnl, ROUND((p.exit_price-p.entry_price)/p.entry_price*100,4) AS ret_pct, ROUND((p.take_profit-p.entry_price)/NULLIF(p.entry_price-p.stop_loss,0),4) AS planned_rr, p.close_reason, p.signal_id, p.exit_signal_id, p.opened_at AS opened_display, CONVERT_TZ(p.opened_at,'+03:00','+00:00') AS opened_utc, p.closed_at AS closed_display, CONVERT_TZ(p.closed_at,'+03:00','+00:00') AS closed_utc, UNIX_TIMESTAMP(p.opened_at) AS opened_epoch, UNIX_TIMESTAMP(p.closed_at) AS closed_epoch, TIMESTAMPDIFF(SECOND,p.opened_at,p.closed_at) AS held_s FROM crypto_ai.paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id;